/* Alpha has no retained pmptool snapshot API; reject that diagnostic. */
static u32 g16_lab_pmptool_size(void)
{
    pr_err("g16_lab: PMP tool snapshot diagnostic is unavailable on alpha\n");
    return 0;
}
static u64 g16_lab_pmptool_word(u32 index)
{
    return U64_MAX;
}

