#define J713_UAT_PTE_AP2		BIT_ULL(7)
#define J713_UAT_PTE_AF			BIT_ULL(10)
#define J713_UAT_PTE_NG			BIT_ULL(11)
#define J713_UAT_PTE_PXN		BIT_ULL(53)
#define J713_UAT_PTE_UXN		BIT_ULL(54)
#define J713_UAT_PTE_GPU_ACCESS		BIT_ULL(55)
/*
 * Intermediate UAT table descriptors contain only the physical address and
 * the valid/table type tuple.  UAT_PTE_AF is a leaf attribute.  Same-build
 * G16 encodePDEFlags() and encodePCEFlags() both return exactly 0x3.
 */
#define J713_UAT_TABLE_DESC_FLAGS	(J713_UAT_PTE_VALID | \
					 J713_UAT_PTE_TYPE)
/*
 * During InitData startup J713 firmware upgrades shared-root L1[2] from the
 * host's PA|3 link to this exact canonical descriptor before publishing ready.
 * Private TTBR0 descriptors remain PA|3.  Keep the runtime producer tuple
 * separate from encodePDEFlags()/encodePCEFlags().
 */
#define J713_UAT_FW_CANONICAL_TABLE_DESC_FLAGS \
	(J713_UAT_PTE_PXN | J713_UAT_PTE_AF | J713_UAT_PTE_AP1 | \
	 J713_UAT_PTE_AP2 | J713_UAT_PTE_ATTR_SHARED | J713_UAT_PTE_TYPE | \
	 J713_UAT_PTE_VALID)
#define J713_UAT_FW_SHARED_FLAGS	(J713_UAT_PTE_GPU_ACCESS | \
					 J713_UAT_PTE_UXN | \
					 J713_UAT_PTE_AF | \
					 J713_UAT_PTE_AP1 | \
					 J713_UAT_PTE_ATTR_SHARED | \
					 J713_UAT_PTE_TYPE | J713_UAT_PTE_VALID)
/*
 * G16's same-build AGXUnifiedAddressTranslator::encodePTEFlags() maps its
 * 16-entry DPRR result into AP[1:0], PXN, and UXN.  Its table contains only
 * results 0..7, so it never emits AP2 (PTE bit 7).  GPU RW/NX is DPRR result
 * 3: PXN|UXN with both AP bits clear.  Read-only executable is result 1: PXN
 * alone.  The apparently counterintuitive PXN bit denies firmware execution
 * while leaving GPU shader execution enabled.  nG distinguishes low user
 * aliases from canonical TTBR1 mappings of the same physical pages.
 */
#define J713_UAT_FW_GPU_RW_SHARED_FLAGS \
	(J713_UAT_PTE_GPU_ACCESS | J713_UAT_PTE_UXN | J713_UAT_PTE_PXN | \
	 J713_UAT_PTE_AF | J713_UAT_PTE_ATTR_SHARED | \
	 J713_UAT_PTE_TYPE | J713_UAT_PTE_VALID)
#define J713_UAT_USER_GPU_RW_NX_SHARED_FLAGS \
	(J713_UAT_PTE_GPU_ACCESS | J713_UAT_PTE_UXN | J713_UAT_PTE_PXN | \
	 J713_UAT_PTE_AF | \
	 J713_UAT_PTE_NG | J713_UAT_PTE_ATTR_SHARED | \
	 J713_UAT_PTE_TYPE | J713_UAT_PTE_VALID)
#define J713_UAT_USER_GPU_RO_EXEC_SHARED_FLAGS \
	(J713_UAT_PTE_GPU_ACCESS | J713_UAT_PTE_PXN | J713_UAT_PTE_AF | \
	 J713_UAT_PTE_NG | J713_UAT_PTE_ATTR_SHARED | \
	 J713_UAT_PTE_TYPE | J713_UAT_PTE_VALID)
/*
 * The captured 25G83 AGXSecureMemoryMap objects for the complete iadd graph
 * all have permission booleans +0x58[5:3] clear and +0x70[39] clear.
 * AGXSecureGart::getUATOptions() consequently returns 0x308 (or 0x108 when
 * its caller selects the alternate map class); both select DPRR lookup result
 * zero in AGXUnifiedAddressTranslator::encodePTEFlags().  With TTBR0 and the
 * shared memory attribute, the exact producer leaf is GPU_ACCESS|AF|nG with
 * neither AP bit nor PXN/UXN.  Keep this captured-resource contract distinct
 * from semantic RO/execute and RW/NX mappings used by the synthetic graph.
 */
#define J713_UAT_USER_GPU_DPRR0_SHARED_FLAGS \
	(J713_UAT_PTE_GPU_ACCESS | J713_UAT_PTE_AF | J713_UAT_PTE_NG | \
	 J713_UAT_PTE_ATTR_SHARED | J713_UAT_PTE_TYPE | \
	 J713_UAT_PTE_VALID)
/*
 * Two independent, executing-stage 25G83 compute-direct captures walked the
 * live context page tables for every submitted IOGPUResource.  All user
 * leaves set AP2 in addition to GPU_ACCESS|AF|nG|shared.  Shader/CDM leaves
 * are executable (UXN clear), while binding/input/output/ESL/compute-pass
 * leaves add UXN.  These are raw table values, not an encodePTEFlags()
 * inference from AGXSecureMemoryMap booleans.
 */
#define J713_UAT_USER_CAPTURE_GPU_EXEC_SHARED_FLAGS \
	(J713_UAT_PTE_GPU_ACCESS | J713_UAT_PTE_AP2 | J713_UAT_PTE_AF | \
	 J713_UAT_PTE_NG | J713_UAT_PTE_ATTR_SHARED | J713_UAT_PTE_TYPE | \
	 J713_UAT_PTE_VALID)
#define J713_UAT_USER_CAPTURE_GPU_DATA_SHARED_FLAGS \
	(J713_UAT_PTE_GPU_ACCESS | J713_UAT_PTE_UXN | J713_UAT_PTE_AP2 | \
	 J713_UAT_PTE_AF | J713_UAT_PTE_NG | J713_UAT_PTE_ATTR_SHARED | \
	 J713_UAT_PTE_TYPE | J713_UAT_PTE_VALID)
#define J713_UAT_FW_DEVICE_FLAGS	(J713_UAT_PTE_GPU_ACCESS | \
					 J713_UAT_PTE_UXN | \
					 J713_UAT_PTE_AF | \
					 J713_UAT_PTE_AP1 | BIT_ULL(2) | \
					 J713_UAT_PTE_TYPE | J713_UAT_PTE_VALID)
#define J713_UAT_FW_DEVICE_MODE0_FLAGS \
	(J713_UAT_FW_DEVICE_FLAGS & ~J713_UAT_PTE_UXN)
#define J713_UAT_FW_PROTECTED_DEVICE_FLAGS \
	(J713_UAT_PTE_PXN | J713_UAT_PTE_AF | J713_UAT_PTE_AP1 | \
	 J713_UAT_PTE_AP2 | BIT_ULL(2) | J713_UAT_PTE_TYPE | \
	 J713_UAT_PTE_VALID)
