/*
 * Exact valid-leaf shape of the successful compute-direct context's L1[7]
 * command/context-store aperture. The allocator uses 128-page runs separated
 * by two-page guard holes. Keep this predicate separate from payload choice:
 * the shape is captured fact, while the opt-in experiment deliberately backs
 * otherwise unknown implicit leaves with one shared zero page.
 */
static bool g16_macos_direct_command_aperture_leaf_valid(unsigned int l2,
							 unsigned int l3)
{
	if (l2 == 0) {
		if (l3 <= 255 || (l3 >= 258 && l3 <= 261) ||
		    (l3 >= 264 && l3 <= 271))
			return true;
		return l3 >= 274 && (l3 - 274) % 130 < 128;
	}

	if (l2 == 1) {
		if (l3 <= 43)
			return true;
		return l3 >= 46 && l3 <= 433 &&
			(l3 - 46) % 130 < 128;
	}

	return false;
}

static const struct g16_fw_queue_priority g16_normal_compute_priority = {
	.class_index = 2,
	.class_index_copy = 2,
	.preemption_mask = 0xffff000000000000ULL,
	.preemptible = 0,
	.subpriority = 0,
	.qos_class = 2,
};

static void g16_lab_initialize_scheduler_context(void *data)
{
	struct g16_fw_scheduler_context *context = data;

	memset(context, 0, sizeof(*context));
	context->owner_index = U8_MAX;
	context->scheduler_index = U8_MAX;
	context->enabled = 1;
	context->engine_context_id = U8_MAX;
}

/* Exact 25G83 main +0x2540 topology block constructed by the G16G kext. */
struct g16_fw_topology_config {
	u32 feature_flags;
	u32 gin_dslot_mask;
	u32 topology_mode_bits;
	u32 dimension_mask_0;
	u32 dimension_mask_1;
	u32 core_limit_mask;
	u32 reserved_2558;
	u32 reserved_255c;
	u64 optional_active_core_bitmap;
	u32 active_core_count;
	u32 reserved_256c;
	u32 valid;
};

static void g16_lab_initialize_topology_config(void *data)
{
	struct g16_fw_topology_config *topology = data;

	BUILD_BUG_ON(offsetof(struct g16_fw_topology_config,
			      gin_dslot_mask) != 0x4);
	BUILD_BUG_ON(offsetof(struct g16_fw_topology_config,
			      dimension_mask_0) != 0xc);
	BUILD_BUG_ON(offsetof(struct g16_fw_topology_config,
			      core_limit_mask) != 0x14);
	BUILD_BUG_ON(offsetof(struct g16_fw_topology_config,
			      optional_active_core_bitmap) != 0x20);
	BUILD_BUG_ON(offsetof(struct g16_fw_topology_config,
			      active_core_count) != 0x28);
	BUILD_BUG_ON(offsetof(struct g16_fw_topology_config, valid) != 0x30);

	memset(topology, 0, sizeof(*topology));
	topology->gin_dslot_mask = 4;
	topology->topology_mode_bits = 6;
	topology->dimension_mask_0 = 3;
	topology->dimension_mask_1 = 7;
	topology->core_limit_mask = 7;
	topology->active_core_count = 8;
	topology->valid = 1;
}

static bool g16_lab_topology_config_matches(const void *data)
{
	const struct g16_fw_topology_config *topology = data;

	return topology->feature_flags == 0 &&
		topology->gin_dslot_mask == 4 &&
		topology->topology_mode_bits == 6 &&
		topology->dimension_mask_0 == 3 &&
		topology->dimension_mask_1 == 7 &&
		topology->core_limit_mask == 7 &&
		topology->reserved_2558 == 0 &&
		topology->reserved_255c == 0 &&
		topology->optional_active_core_bitmap == 0 &&
		topology->active_core_count == 8 &&
		topology->reserved_256c == 0 && topology->valid == 1;
}

