				objects[G16_INITDATA_BARRIER].va +
					J713_COMPUTE_UMA_TABLE_OFFSET;
		if (compute_macos_iadd_aligned_uma_hardware_table)
			g16_initdata_live_usc_private_memory_hardware_table_first =
				objects[
				 G16_INITDATA_USC_PRIVATE_MEMORY_HARDWARE_TABLE].first_page;
		if (compute_macos_direct_pb_hardware_base_alias) {
			g16_initdata_live_parameter_buffer_hardware_table_va =
				objects[
				 G16_INITDATA_PARAMETER_BUFFER_HARDWARE_TABLE].va;
			g16_initdata_live_parameter_buffer_hardware_table_first =
				objects[
				 G16_INITDATA_PARAMETER_BUFFER_HARDWARE_TABLE].first_page;
		}
		g16_initdata_live_pages = pages;
		g16_initdata_live_runtime_first =
			objects[G16_INITDATA_RUNTIME].first_page;
		g16_initdata_live_globals_first =
			objects[G16_INITDATA_GLOBALS].first_page;
		g16_initdata_live_power_first =
			objects[G16_INITDATA_POWER].first_page;
